challenge.solution:
#include <stdio.h>
int main(void) {
    int n; if (scanf("%d", &n) != 1) return 1;
    int answer = n >= 2 ? 1 : 0; for (int d = 2; d * d <= n; d++) if (n % d == 0) { answer = 0; break; } printf("%d\n", answer);
    return 0;
}

