#include <stdio.h>
#include <stdlib.h>

static int min(int a, int b) { return a < b ? a : b; }
static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) { return 1; }
    int a[20000];
    int count = 0;
    while (count < 20000 && scanf("%d", &a[count]) == 1) { count++; }
    int *distance = malloc(((n) > 0 ? (n) : 1) * sizeof *distance);
    if (distance == NULL) { return 1; }
    for (int fill = 0; fill < n; fill++) { distance[fill] = -1; }
    int *queue = malloc(((n) > 0 ? (n) : 1) * sizeof *queue);
    if (queue == NULL) { return 1; }
    for (int fill = 0; fill < n; fill++) { queue[fill] = 0; }
    int head = 0;
    int tail = 0;
    distance[k] = 0;
    queue[tail] = k;
    tail++;
    while (head < tail) {
        int vertex = queue[head];
        head++;
        for (int next = 0; next < n; next++) {
            if (a[vertex * n + next] != 0 && distance[next] == -1) {
                distance[next] = distance[vertex] + 1;
                queue[tail] = next;
                tail++;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%d\n", distance[i]);
    }
    free(distance);
    free(queue);
    return 0;
}

